# Writes routes.txt: the routes the services register, one "METHOD /pattern" per line, read from
# their route files and OpenAPI files at a git ref. TestTableRulesMatchRealRoutes checks every row
# of the allow table against it. Run from this folder:
#   python gen-routes.py <core repo> <ref> <user-service repo> <ref> <app-management repo> <ref> \
#     <local-storage repo> <ref> <virt-management repo> <ref> > routes.txt
import re
import subprocess
import sys

import yaml


def show(repo, ref, path):
    return subprocess.run(["git", "-C", repo, "show", f"{ref}:{path}"], check=True, capture_output=True, text=True, encoding="utf-8").stdout


GROUP = re.compile(r'(\w+)\s*:?=\s*(\w+)\.Group\("([^"]*)"')
ROUTE = re.compile(r'\b(\w+)\.(GET|POST|PUT|DELETE|PATCH|Any)\("([^"]*)"')
MATCH = re.compile(r'\b(\w+)\.Match\(\[\]string\{([^}]*)\},\s*"([^"]*)"')


def echo_routes(source):
    """The routes an echo file registers on e and on its groups, comments left out."""
    prefix = {"e": ""}
    out = []
    for line in source.splitlines():
        line = line.split("//", 1)[0]
        for var, parent, p in GROUP.findall(line):
            prefix[var] = prefix.get(parent, "") + p
        for var, method, p in ROUTE.findall(line):
            if var in prefix:
                out.append(("ANY" if method == "Any" else method, prefix[var] + p))
        for var, methods, p in MATCH.findall(line):
            if var in prefix:
                for m in re.findall(r"http\.Method(\w+)", methods):
                    out.append((m.upper(), prefix[var] + p))
    return out


def openapi_routes(source):
    doc = yaml.safe_load(source)
    base = doc["servers"][0]["url"].rstrip("/")
    return [(m.upper(), base + p) for p, ops in doc["paths"].items() for m in ops if m in ("get", "post", "put", "delete", "patch")]


core, core_ref, users, users_ref, am, am_ref, ls, ls_ref, virt, virt_ref = sys.argv[1:11]
routes = set()
routes.update(echo_routes(show(core, core_ref, "route/v1.go")))
routes.update(openapi_routes(show(core, core_ref, "api/casaos/openapi.yaml")))
routes.update(echo_routes(show(users, users_ref, "route/v1.go")))
routes.update(openapi_routes(show(users, users_ref, "api/user-service/openapi.yaml")))
routes.update(echo_routes(show(am, am_ref, "route/v1.go")))
routes.update(openapi_routes(show(am, am_ref, "api/app_management/openapi.yaml")))
routes.update(echo_routes(show(ls, ls_ref, "route/v1.go")))
routes.update(openapi_routes(show(ls, ls_ref, "api/local_storage/openapi.yaml")))
routes.update(openapi_routes(show(virt, virt_ref, "api/virt_management/openapi.yaml")))
# the core's download by token, a plain handler of its own (route.InitFile), not an echo route
routes.add(("GET", "/v3/file"))

print(f"# generated by gen-routes.py from core {core_ref}, user-service {users_ref}, app-management {am_ref}, local-storage {ls_ref}, virt-management {virt_ref}")
for method, p in sorted(routes, key=lambda r: (r[1], r[0])):
    print(f"{method} {p}")
